// /wq/:code — participant routes for Safety > Workshops.
//
// Public-no-auth: the 6-char session_code in the URL is the capability,
// generated by the facilitator side at /safety-workshops/:slug/sessions.
// CSRF is skipped for this prefix in middleware/csrf.js (matches the
// /sop-sign and /toolbox-attend pattern used by other QR-driven flows).
//
//   GET  /wq/:code             render the quiz UI (no admin layout)
//   POST /wq/:code/start       claim a case (sticky on player_name)
//   POST /wq/:code/submit      save a completed attempt
//   GET  /wq/:code/leaderboard JSON snapshot for the in-quiz live board
//
// The quiz UI (views/workshop-participant/take.ejs) computes scores
// client-side and POSTs the result. We accept the score as submitted but
// store the raw answers in workshop_attempts.answers_json so cheating /
// scoring bugs can be re-derived later from services/workshops/<slug>.js.
'use strict';

const express = require('express');
const router = express.Router();
const { getDb } = require('../db/database');

// Workshop content registry — must mirror routes/safety-workshops.js.
// Each value exposes a `CASES` array used to validate case letters.
const WORKSHOPS = {
  'swms-01': require('../services/workshops/swms-01'),
};

// Locate an open session + its workshop slug in one query. Session codes
// are stored in uppercase (the alphabet has no lowercase letters), so
// .toUpperCase() the input lets a typed-by-hand code work either case.
function getSession(db, code) {
  return db
    .prepare(
      `SELECT s.id AS session_id, s.workshop_id, s.session_code, s.status, s.mode,
              w.slug AS workshop_slug, w.title AS workshop_title
       FROM workshop_sessions s
       JOIN workshop_definitions w ON w.id = s.workshop_id
       WHERE s.session_code = ?`
    )
    .get(code);
}

// Group rows for a session (group mode only). Returns array shaped for
// the participant picker: { name, case_letter, members, claimed }.
function listGroups(db, sessionId) {
  return db
    .prepare(
      `SELECT player_name AS name, case_letter, members_csv, claimed_by_name
       FROM workshop_assignments
       WHERE session_id = ?
       ORDER BY id ASC`
    )
    .all(sessionId)
    .map((r) => ({
      name: r.name,
      case_letter: r.case_letter,
      members: (r.members_csv || '')
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean),
      claimed: !!r.claimed_by_name,
      claimed_by: r.claimed_by_name || null,
    }));
}

// Tiny standalone error page so participants on phones don't see the
// admin dashboard chrome (which they have no session for anyway).
function renderError(res, status, reason) {
  return res.status(status).render('workshop-participant/error', {
    title: 'Workshop session',
    layout: false,
    reason,
  });
}

// =====================================================================
// GET /wq/:code — quiz UI
// =====================================================================
router.get('/:code', (req, res) => {
  const code = String(req.params.code || '').toUpperCase();
  const db = getDb();
  const session = getSession(db, code);
  if (!session) return renderError(res, 404, 'not_found');
  if (session.status !== 'open') return renderError(res, 410, 'closed');

  const module = WORKSHOPS[session.workshop_slug];
  if (!module) return renderError(res, 500, 'no_content');

  // Strip the `c:` (correct) flags from options before they go to the
  // client. The artifact's scoring runs client-side, so the truth flags
  // have to be there — but the client never sees the correctness map
  // until AFTER they lock in an answer (the artifact handles that via
  // post-submit rendering). For the dashboard port we just pass through
  // — the participants are office crew, not adversaries, and the room
  // setting is the social control. If we want server-side scoring later,
  // we strip here and re-derive in /submit.
  res.render('workshop-participant/take', {
    title: session.workshop_title,
    layout: false,
    session: {
      code: session.session_code,
      workshop_slug: session.workshop_slug,
      workshop_title: session.workshop_title,
      mode: session.mode || 'individual',
    },
    groups: session.mode === 'group' ? listGroups(db, session.session_id) : [],
    workshop: {
      slug: module.slug,
      title: module.title,
      cases: module.CASES,
      IMPACTS: module.IMPACTS,
      LIKE: module.LIKE,
      BANDS: module.BANDS,
      CLAUSE_DETAIL: module.CLAUSE_DETAIL,
    },
  });
});

// =====================================================================
// POST /wq/:code/join-group — claim a pre-created team
// =====================================================================
// Group mode only. Body: { group_name, claimer_name? }. Returns the
// group's pre-assigned case letter so the client can roll straight into
// the brief screen with that case. If the group is already claimed by
// someone else, we let the join succeed anyway — the office crew sit at
// one phone per team and multiple scans from the same team's members are
// fine. Display-wise the facilitator dashboard still shows the first
// claimer's name.
router.post('/:code/join-group', (req, res) => {
  const code = String(req.params.code || '').toUpperCase();
  const db = getDb();
  const session = getSession(db, code);
  if (!session) return res.status(404).json({ error: 'session_not_found' });
  if (session.status !== 'open') return res.status(409).json({ error: 'session_closed' });
  if (session.mode !== 'group') return res.status(400).json({ error: 'not_group_mode' });

  const groupName = String((req.body && req.body.group_name) || '').trim();
  const claimer = String((req.body && req.body.claimer_name) || '').trim().slice(0, 60);
  if (!groupName) return res.status(400).json({ error: 'group_required' });

  const row = db
    .prepare(
      `SELECT id, case_letter, claimed_by_name
       FROM workshop_assignments
       WHERE session_id = ? AND player_name = ?`
    )
    .get(session.session_id, groupName);
  if (!row) return res.status(404).json({ error: 'group_not_found' });

  // First scan claims the team. We always record a claim (even without a
  // typed name) so the facilitator dashboard's claimed/total counter
  // ticks up as teams start. If the participant gave a name we display
  // it; otherwise we use the group name as a placeholder. Subsequent
  // scans don't overwrite so the first claimer stays visible.
  if (!row.claimed_by_name) {
    db.prepare(
      'UPDATE workshop_assignments SET claimed_by_name = ?, claimed_at = CURRENT_TIMESTAMP WHERE id = ?'
    ).run(claimer || groupName, row.id);
  }
  return res.json({ caseId: row.case_letter, group_name: groupName });
});

// =====================================================================
// POST /wq/:code/start — claim a case
// =====================================================================
// Sticky on player_name within a session: same name on a refresh = same
// case. First N players (where N = number of cases) get distinct cases;
// once all are taken, additional players get a random repeat.
router.post('/:code/start', (req, res) => {
  const code = String(req.params.code || '').toUpperCase();
  const db = getDb();
  const session = getSession(db, code);
  if (!session) return res.status(404).json({ error: 'session_not_found' });
  if (session.status !== 'open') return res.status(409).json({ error: 'session_closed' });

  const name = String((req.body && req.body.name) || '').trim();
  if (name.length < 2) return res.status(400).json({ error: 'name_required' });
  if (name.length > 60) return res.status(400).json({ error: 'name_too_long' });

  const module = WORKSHOPS[session.workshop_slug];
  if (!module) return res.status(500).json({ error: 'no_content' });
  const validCases = module.CASES.map((c) => c.letter);

  // Sticky lookup — case-insensitive name match.
  const existing = db
    .prepare(
      `SELECT case_letter FROM workshop_assignments
       WHERE session_id = ? AND LOWER(player_name) = LOWER(?)`
    )
    .get(session.session_id, name);
  if (existing) return res.json({ caseId: existing.case_letter, sticky: true });

  // Find unclaimed cases; fall back to the full set if all are taken.
  const taken = db
    .prepare('SELECT case_letter FROM workshop_assignments WHERE session_id = ?')
    .all(session.session_id)
    .map((r) => r.case_letter);
  const free = validCases.filter((c) => !taken.includes(c));
  const pool = free.length ? free : validCases;
  const pick = pool[Math.floor(Math.random() * pool.length)];

  try {
    db.prepare(
      `INSERT INTO workshop_assignments (session_id, player_name, case_letter)
       VALUES (?, ?, ?)`
    ).run(session.session_id, name, pick);
  } catch (e) {
    // UNIQUE(session_id, player_name) race — re-read and return the
    // assignment that landed first.
    const after = db
      .prepare(
        `SELECT case_letter FROM workshop_assignments
         WHERE session_id = ? AND LOWER(player_name) = LOWER(?)`
      )
      .get(session.session_id, name);
    if (after) return res.json({ caseId: after.case_letter, sticky: true });
    return res.status(500).json({ error: 'assignment_failed' });
  }
  return res.json({ caseId: pick, sticky: false });
});

// =====================================================================
// POST /wq/:code/submit — save a completed attempt
// =====================================================================
router.post('/:code/submit', (req, res) => {
  const code = String(req.params.code || '').toUpperCase();
  const db = getDb();
  const session = getSession(db, code);
  if (!session) return res.status(404).json({ error: 'session_not_found' });
  if (session.status !== 'open') return res.status(409).json({ error: 'session_closed' });

  const b = req.body || {};
  const name = String(b.name || '').trim();
  const caseLetter = String(b.caseId || '').toUpperCase();
  const score = Number(b.score);
  const maxScore = Number(b.maxScore);
  const answers = b.answers;

  if (!name || name.length < 2) return res.status(400).json({ error: 'name_required' });
  const module = WORKSHOPS[session.workshop_slug];
  if (!module) return res.status(500).json({ error: 'no_content' });
  const validCases = module.CASES.map((c) => c.letter);
  if (!validCases.includes(caseLetter)) return res.status(400).json({ error: 'bad_case' });
  if (
    !Number.isFinite(score) ||
    !Number.isFinite(maxScore) ||
    maxScore <= 0 ||
    score < 0 ||
    score > maxScore
  ) {
    return res.status(400).json({ error: 'bad_score' });
  }

  // Cap answers_json size so a malicious / buggy client can't blow up
  // the row. 64 KB is far beyond what 8 questions can produce honestly.
  let answersJson = null;
  if (answers != null) {
    try {
      const s = JSON.stringify(answers);
      if (s.length <= 64 * 1024) answersJson = s;
    } catch (e) {
      // ignore — we just won't store the raw answers
    }
  }

  db.prepare(
    `INSERT INTO workshop_attempts
       (session_id, workshop_id, case_letter, player_name, score, max_score,
        answers_json, completed_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)`
  ).run(
    session.session_id,
    session.workshop_id,
    caseLetter,
    name,
    Math.round(score),
    Math.round(maxScore),
    answersJson
  );
  return res.json({ ok: true });
});

// =====================================================================
// GET /wq/:code/leaderboard — JSON for the participant-side live board
// =====================================================================
router.get('/:code/leaderboard', (req, res) => {
  const code = String(req.params.code || '').toUpperCase();
  const db = getDb();
  const session = getSession(db, code);
  if (!session) return res.status(404).json({ error: 'session_not_found' });
  const rows = db
    .prepare(
      `SELECT player_name, case_letter, score, max_score, completed_at
       FROM workshop_attempts
       WHERE session_id = ? AND completed_at IS NOT NULL
       ORDER BY score DESC, completed_at ASC
       LIMIT 50`
    )
    .all(session.session_id);
  res.json({ status: session.status, attempts: rows });
});

module.exports = router;
